SELECT 
FROM gt_bank_wealth_investment
WHERE org_id = #{orgId}

    AND investment_no LIKE CONCAT('%', #{investmentNo}, '%')


    AND product_code LIKE CONCAT('%', #{productCode}, '%')


    AND bank_code = #{bankCode}


    AND investment_status = #{investmentStatus}


    AND investment_date >= #{startDate}


    AND investment_date <= #{endDate}

ORDER BY create_time DESC

SELECT 
FROM gt_bank_wealth_investment
WHERE investment_no = #{investmentNo} AND org_id = #{orgId}

SELECT COALESCE(SUM(investment_amount), 0)
FROM gt_bank_wealth_investment
WHERE org_id = #{orgId}

SELECT COALESCE(SUM(current_value), 0)
FROM gt_bank_wealth_investment
WHERE org_id = #{orgId}

SELECT COALESCE(SUM(expected_return), 0)
FROM gt_bank_wealth_investment
WHERE org_id = #{orgId}

SELECT COUNT(*)
FROM gt_bank_wealth_investment
WHERE investment_no = #{investmentNo} AND org_id = #{orgId}

    AND investment_id != #{excludeId}

SELECT investment_id, investment_no, product_code, 'NEAR_MATURITY' as alertType, '投资即将到期' as alertMessage, maturity_date as alertDate FROM gt_bank_wealth_investment WHERE investment_status = 'ACTIVE' AND maturity_date BETWEEN CURDATE() AND DATE_ADD(CURDATE(), INTERVAL 7 DAY) AND org_id = #{orgId}
UNION ALL
SELECT investment_id, investment_no, product_code, 'LOW_PERFORMANCE' as alertType, '投资收益低于预期' as alertMessage, update_time as alertDate FROM gt_bank_wealth_investment WHERE actual_return_rate < expected_return_rate * 0.8 AND org_id = #{orgId}
